  ('zcrm_5797994000001049108', 'MabLab', NULL, 'Pranav Seshadri', 'Vienna Sparks', 'Cornell Life Changing Labs, Harvard iLabs, Harvard Health Labs Accelerator, MIT I-Corps Spark, Barnard Athena Center Accelerator, InSITE Fellowship, Nucleate Semi-Finalist (New York), Nucleate Finalist (Boston), Northeastern Evolve Accelerator
